namespace sv_826b8878f1a84a94820b9953e6f1960f.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and low-stock alert count, with events so any subscribing component
/// can react to changes without a parent-child relationship.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? _currentWarehouseId;

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Region"),
        new("WH-003", "Warehouse C — West Region"),
        new("WH-004", "Warehouse D — Returns Processing"),
    ];

    public event Action? OnWarehouseChanged;
    public event Action? OnAlertCountChanged;

    private void NotifyWarehouseChanged() => OnWarehouseChanged?.Invoke();
    private void NotifyAlertCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

public sealed record WarehouseInfo(string Id, string Name);

namespace sv_826b8878f1a84a94820b9953e6f1960f.Services;

/// <summary>
/// Simulates checking a database for items below minimum stock levels.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random _random = Random.Shared;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database query with a short delay
        var count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }
}

