@rendermode InteractiveServer
@using sv_826b8878f1a84a94820b9953e6f1960f.Services
@inject WarehouseStateService State
@implements IDisposable

<select class="form-select form-select-sm" value="@State.CurrentWarehouseId"
        @onchange="OnWarehouseSelected" style="max-width: 280px;">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        State.CurrentWarehouseId = e.Value?.ToString() ?? "";
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_826b8878f1a84a94820b9953e6f1960f.Services
@inject WarehouseStateService State
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@State.LowStockCount</span>

@code {
    private string BadgeClass => State.LowStockCount > 0 ? "bg-danger" : "bg-secondary";

    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += OnStateChanged;
        State.OnWarehouseChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= OnStateChanged;
        State.OnWarehouseChanged -= OnStateChanged;
    }
}

