@page "/dashboard"
@rendermode InteractiveServer
@using sv_826b8878f1a84a94820b9953e6f1960f.Services
@inject WarehouseStateService State
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@State.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            <span class="badge @(State.LowStockCount > 0 ? "bg-danger" : "bg-success")">
                @State.LowStockCount
            </span>
        </p>
        <p class="card-text text-muted">
            Items below minimum level. Refreshes every 10 seconds.
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            // Fetch immediately, then poll every 10 seconds
            await PollAlerts();
            _ = StartPollingLoop(_cts.Token);
        }
    }

    private async Task StartPollingLoop(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await PollAlerts();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        // Setting the property notifies ALL subscribers (sidebar badge, etc.)
        State.LowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh alerts for the newly selected warehouse
        await PollAlerts();
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

